""" THIS TRAJECTORY IS GENERATED BY CHATGPT.
Pick-insert object-pose trajectory builder.

The scripted reach->lift->move->align->approach->insert->hold peg trajectory, with an optional
contact-confirmed establish-grasp phase between reach and lift, is specific to the pick-insert task. It
is composed from the task-agnostic primitives in :mod:`src.policy.high_level.utils`.
Pure ``torch`` so it can be unit-tested in isolation; the command term that consumes it lives in
:mod:`src.tasks.pick_insert.mdps.commands`.
"""

from __future__ import annotations

from collections.abc import Sequence

import torch

from src.policy.high_level.trajectory_stepper import StageObjTol
from src.policy.high_level.utils import (
    _as_pose_tensor,
    _with_normalized_quat,
    build_object_pose_sequence_from_keyframes,
)


DEFAULT_RECEPTIVE_POSE = (0.35, 0.0, 0.285, 1.0, 0.0, 0.0, 0.0)

DEFAULT_PICK_INSERT_RECEPTIVE_POSE = (0.35, 0.0, 0.27, 1.0, 0.0, 0.0, 0.0)

# Number of interpolation steps for each of the 7 segments: reach / lift / move / align / approach /
# insert / hold. The reach segment is 0-step: it adds no waypoints, so it just relabels the initial
# waypoint (the object held at its settled pose) as its own stage while the (open) hand reaches the
# grasp pose over the object; the lift segment then raises the grasp goal by lift_height.
DEFAULT_PICK_INSERT_SEGMENT_STEPS = (0, 1, 2, 1, 1, 1, 1)

# tolerances for each of the 7 segments: reach / lift / move / align / approach / insert / hold
DEFAULT_PICK_INSERT_STAGE_OBJECT_TOLERANCES = (
    StageObjTol(0.02, 0.3),  # reach (object held at its settled pose; advance is arm-gated, hand open)
    StageObjTol(0.02, 0.3),  # lift (goal lift_height above the object; the grip must lift it there)
    StageObjTol(0.02, 0.3),  # move
    StageObjTol(0.02, 0.2),  # align
    StageObjTol(0.01, 0.2),  # approach
    StageObjTol(0.005, 0.1),  # insert
    StageObjTol(0.005, 0.1),  # hold
)


def build_pick_insert_object_pose_sequence(
    current_pose: torch.Tensor | Sequence[float],
    receptive_pose: torch.Tensor | Sequence[float] = DEFAULT_PICK_INSERT_RECEPTIVE_POSE,
    segment_steps: Sequence[int] = DEFAULT_PICK_INSERT_SEGMENT_STEPS,
    above_offset: float = 0.15,
    insertion_depth: float = 0.015,
    approach_height: float = 0.08,
    lift_height: float = 0.03,
    enable_grasp_establish: bool = False,
) -> torch.Tensor:
    """Build an interpolated peg-insertion object-pose trajectory.

    Poses use ``(x, y, z, qw, qx, qy, qz)`` in the robot base frame. The returned sequence holds the
    object at ``current_pose`` (reach, while the open hand moves to the grasp pose), raises the grasp
    goal ``lift_height`` above it (lift, where the grip lifts the object to advance -- a grip-secured
    check), then moves above the receptacle, aligns to the receptacle orientation, descends to the
    inserted pose, and holds there. By default this is 7 segments: reach / lift / move / align /
    approach / insert / hold. When ``enable_grasp_establish`` is true, an eighth segment duplicates
    the settled object goal between reach and lift while the hand closes and contact is confirmed. The
    reach segment is typically 0-step (see :data:`DEFAULT_PICK_INSERT_SEGMENT_STEPS`), so it adds no
    waypoints and the object never moves during it. The keyframes are interpolated by the
    shared :func:`~src.policy.high_level.utils.build_object_pose_sequence_from_keyframes` core.
    """
    expected_segments = 8 if enable_grasp_establish else 7
    if len(segment_steps) != expected_segments:
        raise ValueError(f"segment_steps must contain {expected_segments} values.")
    if any(steps < 0 for steps in segment_steps):
        raise ValueError("segment_steps values must be non-negative.")

    current = _with_normalized_quat(_as_pose_tensor(current_pose))
    receptive = _with_normalized_quat(
        _as_pose_tensor(receptive_pose, dtype=current.dtype, device=current.device)
    )

    # Lift keyframe: the object's settled pose raised straight up by lift_height (same orientation).
    # Reach holds the object at its settled pose (goal == current) while the open hand arrives; the
    # lift segment then asks the grip to raise the object to this pose (a controlled, grip-gated lift).
    lifted = torch.cat(
        (
            torch.stack((current[0], current[1], current[2] + current.new_tensor(lift_height))),
            current[3:7],
        )
    )

    above_current = torch.cat(
        (
            torch.stack(
                (
                    receptive[0],
                    receptive[1],
                    receptive[2] + current.new_tensor(above_offset),
                )
            ),
            current[3:7],
        )
    )
    above_aligned = torch.cat((above_current[:3], receptive[3:7]))
    approach = torch.cat(
        (
            torch.stack(
                (
                    receptive[0],
                    receptive[1],
                    receptive[2] + current.new_tensor(insertion_depth + approach_height),
                )
            ),
            receptive[3:7],
        )
    )
    inserted = torch.cat(
        (
            torch.stack(
                (
                    receptive[0],
                    receptive[1],
                    receptive[2] + current.new_tensor(insertion_depth),
                )
            ),
            receptive[3:7],
        )
    )

    # Leading ``current`` is the reach keyframe: the object goal is held at its settled pose while the
    # open hand reaches the grasp pose. The optional duplicate holds that pose while the hand closes;
    # ``lifted`` then raises the grasp goal so the grip lifts the object before transport.
    if enable_grasp_establish:
        # Duplicate the settled pose so stage 1 can hold the arm still while contact is established.
        key_poses = (
            current,
            current,
            current,
            lifted,
            above_current,
            above_aligned,
            approach,
            inserted,
            inserted,
        )
    else:
        key_poses = (current, current, lifted, above_current, above_aligned, approach, inserted, inserted)
    return build_object_pose_sequence_from_keyframes(key_poses, segment_steps)


__all__ = [
    "DEFAULT_RECEPTIVE_POSE",
    "build_pick_insert_object_pose_sequence",
]
